# Prose proofing deliberately does not alter identifiers, evidence quotes, formulas, URLs or hashes.
def prose(s):
 for a,z in {'all26':'all 26','byte=8bits':'byte = 8 bits','score0.':'score 0.','time10.':'time 10.','age0.':'age 0.','at9.':'at 9.','at4.':'at 4.','because0.':'because 0.','takes80ms':'takes 80 ms','at30Hz':'at 30 Hz','is1536000':'is 1536000','to26':'to 26','At30':'At 30','is46128000':'is 46128000','Compute640':'Compute 640','Subtract48000':'Subtract 48000','from40000000':'from 40000000','Convert80ms':'Convert 80 ms','to0.080s':'to 0.080 s','rate1/':'rate 1/','Compare30Hz':'Compare 30 Hz','with12.5Hz':'with 12.5 Hz','from10.0s':'from 10.0 s','the0.80':'the 0.80','age5.00':'age 5.00','Compare0.60s':'Compare 0.60 s','with0.30s':'with 0.30 s','score0.90':'score 0.90','sad,score':'sad, score','sad, score0.90,captured':'sad, score 0.90, captured'}.items():s=s.replace(a,z)
 s=re.sub(r'(?<=\d)(ms|Hz|s|bits)(?=\b)',r' \1',s)
 s=re.sub(r',(?!\s)(?=[A-Za-z])',', ',s)
 s=s.replace('Age0.','Age 0.').replace('below0.','below 0.').replace('s:0.','s: 0.')
 s=s.replace('branch:110','branch: 110').replace('t=5.00 s','t = 5.00 s').replace('age≤','age ≤ ').replace('score≥','score ≥ ').replace('scores≥','scores ≥ ')
 return s
