 sol['justification']=' '.join(sol['optionExplanations'][o['id']].removeprefix('Correct. ')for o in q['options']if o['id']in q['correctOptionIds']);sol['simpleExplanation']=sol['justification'];sol['misconceptions']=[sol['optionExplanations'][o['id']].removeprefix('Incorrect. ')for o in q['options']if o['id']not in q['correctOptionIds']]
 for f in sol['formulas']:f['assumptions']=[prose(x)for x in f['assumptions']]
